@Component("issue-handler")
@ProcessingGroup("issue-processing-group")
public class IssueEventHandler {
	
	// core constructor
	IssueEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateIssueEvent
     */
    @EventHandler
    public void handle( CreateIssueEvent event) {
        entityManager.persist(new Issue(event.getIssueId(), event.getTitle(), event.getOpenedDate(), event.getClosedDate(), event.getRisk(), event.getFinding(), event.getCorrectiveActions(), event.getControl(), event.getIssueType(), event.getPriority(), event.getStatus()));
    }

    /*
     * @param	event UpdateIssueEvent
     */
    @EventHandler
    public Issue handle( UpdateIssueEvent event) {
    	entityManager.merge(new Issue(event.getIssueId(), event.getTitle(), event.getOpenedDate(), event.getClosedDate(), event.getRisk(), event.getFinding(), event.getCorrectiveActions(), event.getControl(), event.getIssueType(), event.getPriority(), event.getStatus()));
    }
    
    /*
     * @param	event DeleteIssueEvent
     */
    @EventHandler
    public void on( DeleteIssueEvent event) {
    	Issue entity = new Issue();
   
    	// ------------------------------------------
    	// apply the IssueId
    	// ------------------------------------------
    	entity.setIssueId( event.getIssueId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final IssueRepository issueEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(IssueEventHandler.class.getName());

}
